struct Base {
    virtual void draw() const { std::cout << "Base\n"; }
    virtual ~Base() = default;
};
struct Derived : Base {
    void draw() const override { std::cout << "Derived\n"; }
};

Derived d;
Base& b = d;
b.draw();       // chosen at runtime

struct Base {
    void f(int)    { std::cout << "Base::f(int)\n"; }
    void f(double) { std::cout << "Base::f(double)\n"; }
};
struct Derived : Base {
